-- Source: QA.csv (100 rows; question and answer preserved verbatim)
-- Source SHA-256: 534bfcb65095a40c88db3d1916c98fed304aa0fb4e2c2f8292eb6f43656f7504
-- Model: sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2
-- Model revision: e8f8c211226b894fcb81acc59f3b34ba3efd5f42
-- Encoding input: question + "\n" + answer (no query/passage prefix)
-- Pooling: attention-mask-aware mean pooling; L2 normalization; 384 dimensions.
-- max_seq_length=512; longest input=79 tokens; no input truncated.
-- These are actual locally computed embeddings, not placeholders.
-- Run this entire file in the Supabase SQL Editor.
-- This creates public.qa and does not modify the source CSV files.
-- Re-running updates embeddings for matching question/answer pairs.
-- Other existing rows are retained. An incompatible existing table causes an error.
-- API access is backend-only by default: RLS is enabled with no client policies.
-- Use a server-side service_role client; never expose its key in a browser.
-- Reference: https://supabase.com/docs/guides/ai/vector-columns
-- Model card: https://huggingface.co/sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2

begin;
set local standard_conforming_strings = on;

create schema if not exists extensions;
create extension if not exists vector with schema extensions;

-- Supabase normally installs pgvector in extensions. Fail clearly if an existing
-- installation uses another schema rather than altering that installation.
do $check_vector_schema$
begin
    if not exists (
        select 1 from pg_catalog.pg_extension as e
        join pg_catalog.pg_namespace as n on n.oid = e.extnamespace
        where e.extname = 'vector' and n.nspname = 'extensions'
    ) then
        raise exception 'pgvector must be installed in the extensions schema for this script';
    end if;
end;
$check_vector_schema$;

create table if not exists public.qa (
    id bigint generated always as identity primary key,
    question text not null,
    answer text not null,
    embedding extensions.vector(384) not null,
    constraint qa_question_answer_key unique (question, answer)
);

alter table public.qa enable row level security;

comment on column public.qa.embedding is
    'sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2@e8f8c211226b894fcb81acc59f3b34ba3efd5f42; input=question + LF + answer; mean pooling; max_seq_length=512; L2 normalized; dimensions=384. Queries MUST use the same model, pooling and normalization.';


on conflict (question, answer) do update
set embedding = excluded.embedding;

-- At this dataset size, exact cosine search avoids approximate-index recall loss.
-- Convert a new user question into a vector with the SAME model and call
-- rpc('match_qa', {query_embedding: [...384 floats...], match_count: 5}).
-- The default threshold applies no similarity cutoff; calibrate it on real queries.
-- This function respects the caller's table permissions and row-level security.
create or replace function public.match_qa(
    query_embedding extensions.vector(384),
    match_count integer default 5,
    match_threshold double precision default -1.0
)
returns table (
    id bigint,
    question text,
    answer text,
    similarity double precision
)
language sql
stable
security invoker
set search_path = ''
as $match_qa$
    select
        q.id,
        q.question,
        q.answer,
        1.0 - (q.embedding operator(extensions.<=>) query_embedding) as similarity
    from public.qa as q
    where 1.0 - (q.embedding operator(extensions.<=>) query_embedding) >= match_threshold
    order by q.embedding operator(extensions.<=>) query_embedding asc, q.id asc
    limit greatest(0, least(coalesce(match_count, 5), 100));
$match_qa$;

commit;

-- Confirm the imported records and vector dimensions:
select count(*) as total_rows,
       min(extensions.vector_dims(embedding)) as min_dimensions,
       max(extensions.vector_dims(embedding)) as max_dimensions
from public.qa;

